import{fetchCohortJSON}from'./current-cohort-loader.js';import{structuredModelHTML}from'./structured-model-view.js';
import {expandedPayPanel} from './expanded-pay-ui.js';
import{newCohortLabels,selectCohortPopulation,authoredExperience,priorityLabels}from'./cohort-049-meta.js';
import{cohort049FinalState,cohort049Audit}from'./cohort-049-audit.js';
import {educationBadges,opportunitiesPanel} from './career-opportunities-ui.js';
import {authClient,getPrivateReviewCases} from './firebase-client.js?v=0.36.0';
import {modelLabCase,labSummary,modelLabPlan} from './model-lab-engine.js';
import {renderPlan} from './developer-experiment-ui.js';
import {careerScopeNotes,educationTradeoff} from './career-review-logic.js';
import {occupationById} from './occupation-data.js';
import {formatSalary} from './salary-progression.js';
const h=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const ul=a=>a.length?'<ul>'+a.map(t=>'<li>'+t+'</li>').join('')+'</ul>':'<p>None featured.</p>',names=a=>a.length?a.map(x=>h(x.title)).join(' · '):'None featured.',money=n=>Number.isFinite(n)?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n):'Not entered';
const axes=[['R','Realistic'],['I','Investigative'],['A','Artistic'],['S','Social'],['E','Enterprising'],['C','Conventional']];
const scores=(a,full=false)=>'<div class="score-grid '+(full?'case-scores':'')+'">'+axes.map(([k,n],i)=>'<div class="score"><span>'+k+(full?' · '+n:'')+'</span><b>'+h(a[i])+'</b><small>/ 40</small><div class="score-bar"><i style="width:'+Math.max(0,Math.min(100,(a[i]||0)*2.5))+'%"></i></div></div>').join('')+'</div>';
const group=r=>r.phase==='development'||r.phase==='holdout'?'original':r.phase;
let publicRows=[],privateCases=[],user=null,loading=false,experimentLoaded=false,filterChanged=false,listLimit=60;
const $=id=>document.getElementById(id),privateStatus=$('private-status');
const cohortParam=new URL(location.href).searchParams.get('cohort');
const labels={original:'Original 100',development:'Original · development',holdout:'Original · holdout',supplement:'Additional 24',legacy:'Older 24 · parallel review',private:'Owner-only 6',...newCohortLabels};
$('cohort').innerHTML='<option value="all">All base profiles</option><option value="all-rows">Base profiles + diagnostic variants</option>'+Object.entries(labels).map(([id,title])=>'<option value="'+id+'">'+h(title)+'</option>').join('');
const validCohort=value=>['all','all-rows',...Object.keys(labels)].includes(value);
if(validCohort(cohortParam))$('cohort').value=cohortParam;
const metadataHTML=c=>c.cohort049?'<p class="cohort-metadata">'+h(c.cohort049.kind==='diagnostic'?'Diagnostic variant · paired control':'New 0.49 base profile')+(c.cohort049.intervention?' · '+h(c.cohort049.intervention):'')+(c.cohort049.description?' · '+h(c.cohort049.description):'')+(c.cohort049.baseId?' · Parent: <a href="./model-lab.html?case='+encodeURIComponent(c.cohort049.baseId)+'">'+h(c.cohort049.baseId)+' →</a>':'')+'</p>':'';
function experienceHTML(c){const state=c.cohort049?cohort049FinalState(c):c.experimentState;return '<section><h2>Optional experience & priorities</h2><p>These are simulated experience answers, not measured aptitude. Authored answers and the answers applied in the main replay can differ.</p><dl><dt>Authored optional experience</dt><dd>'+h(JSON.stringify(authoredExperience(c)))+'</dd><dt>Applied optional experience</dt><dd>'+h(JSON.stringify(state?.profileJourney?.skills||{}))+'</dd><dt>Applied priorities</dt><dd>'+h((state?.priorities||[]).map(k=>priorityLabels[k]||k).join(' · ')||'None applied')+'</dd></dl></section>';}
function card(r){return '<article class="model-card"><h3><a href="?case='+encodeURIComponent(r.id)+'">'+h(r.name)+' →</a></h3><p>'+h(labels[r.phase]||labels[group(r)]||r.phase)+' · '+h(r.id)+'</p>'+(r.cohort056?'<p>Structured simulation · no independent case review</p>':'')+metadataHTML(r)+scores(r.scores)+'<p><strong>Pathways:</strong> '+names(r.pathways)+'</p><p><strong>Work-led:</strong> '+names(r.workPathways)+'</p><p><strong>Current Top:</strong> '+names(r.careers)+'</p><p>No automatic career choice.</p></article>';}
function renderList(){const query=$('model-search').value.trim().toLowerCase(),cohort=!filterChanged&&validCohort(cohortParam)?cohortParam:$('cohort').value;$('cohort').value=cohort;const all=[...privateCases.map(c=>labSummary(modelLabCase(c))),...publicRows],population=cohort==='original'?all.filter(r=>group(r)==='original'):selectCohortPopulation(all,cohort),filtered=population.filter(r=>JSON.stringify([r.name,r.id,r.field,r.careers,r.pathways,r.workPathways]).toLowerCase().includes(query));$('model-count').textContent=filtered.length+' models in this view · first '+Math.min(listLimit,filtered.length)+' shown'+(!privateCases.length?' · six private models require owner sign-in':'');$('model-list').innerHTML='<div class="lab-grid">'+filtered.slice(0,listLimit).map(card).join('')+'</div>';$('library-more').hidden=filtered.length<=listLimit;}
function answers(rows,c){return '<ol class="questions">'+rows.map(q=>{const rationale=c.response?.responseRationales?.find(r=>r.items.includes(q.id)),omitted=c.optionalOmitted?.includes(q.id)||c.askedQuestionIds&&['interest','pathway','skill','values','context'].includes(q.kind)&&!c.askedQuestionIds.includes(q.id);return '<li value="'+q.number+'" data-question="'+h(q.id)+'"><strong>'+h(q.prompt)+'</strong><p class="answer">'+(omitted?'Optional · not used. Inferred answer: ':'Answer: ')+h(q.answer)+'</p><ul class="answer-options">'+q.options.map(o=>'<li>'+(o.selected?'✓ ':'')+h(o.label)+'</li>').join('')+'</ul>'+(rationale?'<details><summary>Why this answer?</summary><p>'+h(rationale.reason||rationale.evidence||'No rationale recorded')+'</p><p>Inference confidence: '+h(rationale.confidence)+'. This is an imagined answer, not an observation.</p></details>':'')+'</li>';}).join('')+'</ol>';}
function renderMatches(lab){if(lab.currentAudit){const a=lab.currentAudit;return '<h2>Current career offers</h2><p><strong>Initial Top:</strong> '+names(a.first.top)+'</p><p><strong>Final Top:</strong> '+names(a.top)+'</p><p><strong>Needs confirmation:</strong> '+names(a.needsConfirmation)+'</p><p><strong>Other displayed options:</strong> '+names(a.other)+'</p><p>Initial and final offers use the same frozen current rules. Later reflections can support an interest match; they do not measure aptitude or record a career choice.</p><p><a href="./model-match-chart.html?query='+encodeURIComponent(lab.id)+(lab.phase==='diagnostic049'?'&amp;cohort=diagnostic049':'')+'">Inspect exact interests, unresolved questions and starting-pay coverage →</a></p>'+ul(a.top.map(p=>'<h3>'+h(p.title)+'</h3><p>'+h(p.confirmation?.detail||p.reason)+'</p>'+ul((p.confirmation?.questions||[]).map(q=>h(q.prompt)+'<br><strong>'+h(q.answer?.response||'Not answered')+' · '+h(q.answer?.confidence||'unrated')+'</strong><br>'+h(q.answer?.evidence||''))))); }const r=lab.current;return '<h2>Earlier saved career options</h2><p><strong>Final matches:</strong> '+names(r.professions)+'</p><p>These are work options to compare, not chosen careers. A correlation is not a percentage chance of success.</p>'+ul(r.professions.map(p=>{const row=r.inputs.professionRows.find(x=>x.id===p.id);return '<h3>'+h(p.title)+'</h3>'+educationBadges(occupationById(p.id))+'<p>'+ (p.basis==='tasks'?'Repeated task choices support exploring this work. The six-score profile does not independently support it.':'The six-score interest pattern and repeated task choices both support exploring this work.')+'</p>'+ul(p.reasons.map(h))+'<p>'+row.taskSupport+' of '+row.taskTotal+' task questions connect with this job.</p>'+(row.r<0?'<p class="lab-caution">Your overall interest pattern points elsewhere. Try the tasks before deciding.</p>':'')+(row.sharedWork?'<p class="lab-caution">These tasks fit several jobs. The exact specialty is still open.</p>':'')+(row.educationTradeoff?'<p class="lab-caution">'+h(row.educationTradeoff)+'</p>':'')+(row.scopeNotes?.length?ul(row.scopeNotes.map(h)):'');}))+'<details><summary>All jobs, task evidence and correlations</summary>'+ul(r.inputs.professionRows.map(row=>'<strong>'+h(row.title)+'</strong> · r '+(Number.isFinite(row.r)?row.r.toFixed(3):'unavailable')+' · '+row.taskSupport+'/'+row.taskTotal+' task groups · '+(row.featured?'Featured':row.comparisonOnly?'Shared-task alternative':'Not featured')+'<p>'+h(row.label)+'</p>'))+'</details>';}
function planView(lab,id,state=lab.experimentState){const item=state===lab.experimentState?lab.plans.find(p=>p.id===id)||modelLabPlan(state,id):modelLabPlan(state,id);if(!item)return;const p=item.plan;if(occupationById(id)?.expandedDegree){$('selected-plan').innerHTML='<h3>'+h(p.career.title)+' · comparison plan</h3><p>This preview is not a student decision.</p><p><strong>Preparation:</strong> '+h(p.preparation)+'</p>'+ul(p.preparationDetails.map(h))+''+expandedPayPanel(state,occupationById(id))+'<p><a href="../student-view.html?case='+encodeURIComponent(lab.id)+(lab.cohort049?'&amp;replay=final':'')+'&amp;career='+encodeURIComponent(id)+'#/plan">Open this profession in a student comparison →</a></p><h3>Next steps</h3>'+ul(p.steps.filter(a=>!a.done).map(a=>'<strong>'+h(a.title)+'</strong><p>'+h(a.detail)+'</p>'));document.querySelector('#plan-options')?.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preview===id)));return;}const gap=p.lifestyle.result.remaining,spending=p.lifestyle.result.spending,near=gap<0&&Math.abs(gap)<spending*.05;const copy=near?'Starting pay is close, but just below this budget. Small changes could cover the gap.':gap<0?'Starting pay does not cover this lifestyle.':'Starting pay covers this lifestyle in this scenario.';const row={educationTradeoff:educationTradeoff(state,occupationById(id))};$('selected-plan').innerHTML='<h3>'+h(p.career.title)+' · comparison plan</h3><p>This preview is not a student decision.</p><p><a class="student-view-link" href="../student-view.html?case='+encodeURIComponent(lab.id)+(lab.cohort049?'&amp;replay=final':'')+'&amp;career='+encodeURIComponent(id)+'#/plan">See this plan as the student →</a></p><p><strong>Preparation:</strong> '+h(p.preparation)+'</p>'+ul(p.preparationDetails.map(h))+(row?.educationTradeoff?'<p class="lab-caution">'+h(row.educationTradeoff)+'</p>':'')+(p.paidTraining?'<p><strong>First paid training stage:</strong> '+h(p.paidTraining.label)+' · '+formatSalary(p.selectedSalary.annualGross)+' a year. Required study comes before this stage.</p>':'')+'<div class="lab-table-wrap"><table><caption>Annual pay before tax · Austin reference'+(p.paidTraining?' · after qualifying':'')+'</caption><thead><tr>'+p.salaryStages.map(s=>'<th>'+h(s.label)+'</th>').join('')+'</tr></thead><tbody><tr>'+p.salaryStages.map(s=>'<td><strong>'+h(s.display)+'</strong></td>').join('')+'</tr></tbody></table></div><p>Starting pay is an estimate. The 5/10/20-year amounts are planning illustrations, not measured experience averages or promised raises. These years start with the first qualified job. Regular paid work is assumed; freelance hours and income can vary.</p><p class="'+(gap<0?'lab-caution':'lab-good')+'"><strong>'+copy+'</strong> About '+money(Math.abs(gap))+' a month '+(gap<0?'short':'left')+'.</p><p><strong>Income needed:</strong> '+formatSalary(p.incomeRange.low)+'–'+formatSalary(p.incomeRange.high)+' a year before tax.</p><details><summary>Education costs and funding</summary><p>Reference study budget before aid: '+money(item.budget.cost)+' · '+item.budget.years+' study years.</p>'+ul(item.budget.parts.map(x=>'<strong>'+h(x.label)+' · '+money(x.amount)+'</strong><p>'+h(x.scope)+'</p>'))+'<p>Includes the costs described in the reference, not a binding tuition quote. Still needs funding: '+money(item.funding.unfunded)+'. Loans, grants and family help are not invented.</p><p>Training is not paid for by the salary comparison unless entered loan payments are linked.</p></details><h3>Next steps</h3>'+ul(p.steps.filter(a=>!a.done).map(a=>'<strong>'+h(a.title)+'</strong><p>'+h(a.detail)+'</p>'))+'<details><summary>Full plan, finances and earlier completed work</summary>'+renderPlan({...lab.current,plan:p,planReason:'Explicit career comparison. No automatic career decision.'})+'</details>';document.querySelector('#plan-options')?.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preview===id)));}
async function openCase(id){document.querySelector('main>header').hidden=true;$('private-access').hidden=publicRows.some(r=>r.id===id);$('library').hidden=true;$('case').hidden=false;let raw=privateCases.find(c=>c.id===id);if(!raw){if(!publicRows.some(c=>c.id===id)){$('case').innerHTML='<h2>Private model</h2><p>Sign in above with the owner account to open this case.</p>';return;}raw=await fetchCohortJSON('./lives/'+encodeURIComponent(id)+(/^scale056-/.test(id)?'.json.gz':'.json'));}if(raw.cohort056){document.title=raw.biography.name+' · Model review';$('case').innerHTML=structuredModelHTML(raw);const focus=location.hash&&document.getElementById(location.hash.slice(1));if(focus){if(focus.tagName==='DETAILS')focus.open=true;focus.scrollIntoView({block:'start'});}return;}const currentSummary=publicRows.find(r=>r.id===id);const lab=modelLabCase(raw.cohort049?{...raw,experimentState:cohort049FinalState(raw)}:raw),bio=lab.biography,input=lab.current.inputs;if(raw.cohort049){lab.currentAudit=cohort049Audit(raw);const currentIds=new Set(lab.plans.map(p=>p.id));for(const p of lab.currentAudit.top)if(!currentIds.has(p.id)){const plan=modelLabPlan(lab.experimentState,p.id);if(plan)lab.plans.push(plan);}}let previewState=lab.experimentState;document.addEventListener('fieldguide-lab-rerun',e=>{previewState=e.detail.state;});document.title=lab.name+' · Model review';$('case').innerHTML='<h1>'+h(lab.name)+'</h1><section class="guide-input-panel"><h2>Current supported Top</h2><p>'+names(currentSummary?.careers||[])+'</p><a href="./model-match-chart.html?query='+encodeURIComponent(lab.id)+'">Current offers, evidence and lifestyle →</a><p>Earlier questionnaire and comparison records below are preserved snapshots.</p></section><p><a href="../student-view.html?case='+encodeURIComponent(lab.id)+(lab.cohort049?'&amp;replay=final':'')+'#/journey/professions">See results as the student →</a></p><p>'+h(labels[lab.phase]||labels[group(lab)]||lab.phase)+' · fictional age '+h(bio.age)+' · '+h(lab.id)+'</p>'+metadataHTML(raw)+'<p>Responses were inferred from a fictional life history. They are not observed student answers. No aptitude is measured.</p>'+experienceHTML(raw)+'<nav class="case-jump"><a href="#intermediate">Scores & pathways</a><a href="#refined">Career matches</a><a href="#plan">Compare plans</a><a href="#profile">All answers</a></nav><details id="history"><summary>Life history and current interests</summary><p>'+h(bio.selfDescription)+'</p>'+ul(Object.entries(bio.background||{}).map(([k,v])=>'<strong>'+h(k)+'</strong>: '+h(Array.isArray(v)?v.join(' · '):v)))+ul(bio.timeline.map(t=>'<strong>Age '+h(t.ages)+'</strong><p>'+h(t.story)+'</p>'))+'<h3>Life now</h3>'+ul(Object.entries(bio.currentLife||{}).map(([k,v])=>'<strong>'+h(k)+'</strong>: '+h(Array.isArray(v)?v.join(' · '):v)))+'</details>'+(lab.review?'<details><summary>Independent review · fit, unrealistic assumptions and next steps</summary><p>'+h(lab.review.disposition)+'</p><p>'+h(lab.review.actualInterestsAndEvidence)+'</p><p>'+h(lab.review.answerReview.uncertainOrOverextended)+'</p><p>'+h(lab.review.conditionalPlanReview.limits)+'</p><p><strong>Better next step:</strong> '+h(lab.review.conditionalPlanReview.practicalTest)+'</p></details>':'')+'<section id="intermediate">'+(lab.flags?.length?'<details><summary>Review flags and inference limits</summary>'+ul(lab.flags.map(f=>'<strong>'+h(f.kind)+'</strong><p>'+h(f.detail)+'</p>'))+'</details>':'')+'<h2>Six RIASEC interests</h2>'+scores(lab.current.rawScores,true)+'<p>Each score is out of 40. These are interest totals, not ability, percentiles, or success odds.</p><p><strong>Profile-supported pathways:</strong> '+names(lab.current.pathways)+'</p><p><strong>Work-led pathways:</strong> '+names(lab.current.workPathways)+'</p><p><strong>Field explored:</strong> '+h(lab.current.family)+'. '+h(lab.response.branchReason)+'</p><p>We show fewer pathways when fewer fit. Work-led options can differ from the overall profile.</p></section><section id="refined">'+renderMatches(lab)+opportunitiesPanel(lab.experimentState,{compact:true,compareOnly:true})+'</section><section id="plan"><h2>Compare plans before choosing</h2><p>No final career is assigned. Pick an option to see its education, pay, lifestyle and next steps.</p><div id="plan-options" class="plan-options">'+lab.plans.map(p=>'<button data-preview="'+h(p.id)+'" aria-pressed="false">'+h(p.plan.career.title)+'</button>').join('')+'</div><div id="selected-plan" aria-live="polite"></div>'+(raw.cohort049?'':'<details><summary>Earlier first-career preview · retained record</summary><p>The earlier review automatically previewed '+h(lab.previousPlan?.career?.title||'no career')+'. That was a simulation convenience, not a student choice. The frozen record remains unchanged.</p></details>')+'</section><section id="experiment-panel"><h2>Edit a copy and rerun</h2><p>Frozen answers stay intact. This does not touch your saved student guide.</p><div class="tools"><button id="edit-experiment" disabled>Edit answers</button><button id="run-experiment" disabled>Rerun matching</button><button id="reset-experiment" disabled>Reset to original</button><button id="download-experiment" disabled>Download experiment</button><button id="print-view">Print / save PDF</button></div><p id="experiment-status" role="status">Loading tools…</p><div id="experiment-settings" hidden></div><div id="experiment-comparison" hidden></div></section><nav class="jump"><button id="run-experiment-sticky" hidden disabled>Rerun matching</button><span id="experiment-pending-tag" role="status"></span></nav><details><summary>Expanded view · every question and answer</summary><p>Only questions used on the main route contributed to these results. Inferred optional answers remain labeled.</p><label><input id="show-options" type="checkbox"> Show answer options</label><section id="profile"><h2>Profile answers</h2>'+answers(lab.authoredInputs.profile,lab)+'</section><section id="followups"><h2>Profession follow-ups</h2>'+answers(input.followups,lab)+'</section><section id="lifestyle"><h2>Lifestyle answers</h2>'+answers(input.lifestyle,lab)+'</section></details><script type="application/json" id="experiment-data">'+JSON.stringify({id:lab.id,name:lab.name,family:input.family,state:lab.experimentState,planPolicy:'explicit'}).replaceAll('<','\\u003c')+'</script>';
 $('case').addEventListener('click',e=>{const b=e.target.closest('[data-preview]');if(b){if(!$('selected-plan'))$('plan').insertAdjacentHTML('beforeend','<div id="selected-plan" aria-live="polite"></div>');planView(lab,b.dataset.preview,previewState);$('selected-plan').scrollIntoView({block:'start',behavior:'smooth'});}});$('show-options').addEventListener('change',e=>document.body.classList.toggle('show-options',e.target.checked));$('print-view').addEventListener('click',()=>window.print());const focused=document.getElementById(location.hash.slice(1));if(focused){for(let n=focused;n;n=n.parentElement)if(n.tagName==='DETAILS')n.open=true;focused.scrollIntoView({block:'start'});}if(!experimentLoaded){experimentLoaded=true;await import('./experiment-035.js?v=0.38.0');}}
async function loadPrivate(){if(loading)return;loading=true;try{const session=await authClient.getSession();user=session.data?.user;$('lab-signin').hidden=!!user;$('lab-signout').hidden=!user;if(!user){privateCases=[];privateStatus.textContent='Sign in with the owner Google account to include the six private histories.';}else{try{privateCases=await getPrivateReviewCases();privateStatus.textContent=privateCases.length+' private models available to '+user.email+'. Other visitors cannot read them.';}catch{privateCases=[];privateStatus.textContent='This Google account cannot read the owner’s private model library.';}}renderList();const id=new URL(location.href).searchParams.get('case');if(id)await openCase(id);}finally{loading=false;}}
$('lab-signin').addEventListener('click',async()=>{try{await authClient.googleSignIn();await loadPrivate();}catch(e){privateStatus.textContent=e.code==='auth/unauthorized-domain'?'Sign in on the published Fieldguide website to view private models.':e.code==='auth/popup-blocked'?'Allow the Google sign-in window, then try again.':'Sign-in did not finish. Please try again.';}});$('lab-signout').addEventListener('click',async()=>{await authClient.signOut();location.href='./model-lab.html';});$('library-more').addEventListener('click',()=>{listLimit+=60;renderList();});$('model-search').addEventListener('input',()=>{listLimit=60;renderList();});$('cohort').addEventListener('change',()=>{filterChanged=true;listLimit=60;renderList();});
try{publicRows=(await fetch('./model-lab-data.json?v=0.36.0').then(r=>r.json())).rows;renderList();await loadPrivate();authClient.watch(next=>{if(next?.id!==user?.id)location.reload();});}catch(e){$('case').hidden=false;$('case').innerHTML='<p>'+h(e.message)+'</p><a href="./life-models.html">Open the earlier library →</a>';}
